/**
 * @summary Upload LOA Document
 * @description Submit LOA document (pdf format) under the account.
 * @link /accounts/{accountId}/addressing/loa_documents
 */
export async function ipAddressManagementPrefixesUploadLoaDocument(
	{
		pathParams,
		body,
		config,
	}: {
		pathParams: IpAddressManagementPrefixesUploadLoaDocumentPath;
		body: IpAddressManagementPrefixesUploadLoaDocumentBody;
		config?: Partial<FetcherConfig> & { client?: typeof defaultClient };
	} = {} as any,
) {
	const { client: request = defaultClient, ...requestConfig } = config ?? {};

	if (pathParams?.accountId == null || String(pathParams.accountId) === "") {
		throw new Error(`Missing required path parameter: accountId`);
	}
	const formData = new FormData();
	if (body) {
		for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
			for (const item of Array.isArray(value) ? value : [value]) {
				if (typeof item === "string" || item instanceof Blob) {
					formData.append(key, item);
				} else if (
					typeof item === "number" ||
					typeof item === "boolean" ||
					typeof item === "bigint"
				) {
					formData.append(key, String(item));
				} else if (item != null) {
					formData.append(key, JSON.stringify(item));
				}
			}
		}
	}
	const data = await request<
		IpAddressManagementPrefixesUploadLoaDocumentResponse,
		ErrorWrapper<IpAddressManagementPrefixesUploadLoaDocumentStatus400>,
		FormData,
		Record<string, string>,
		Record<string, string>,
		IpAddressManagementPrefixesUploadLoaDocumentPath
	>({
		method: "POST",
		url: `/accounts/${encodeURIComponent(String(pathParams.accountId))}/addressing/loa_documents`,
		body: formData,
		...requestConfig,
		headers: { "Content-Type": "multipart/form-data", ...requestConfig.headers },
	});

	return data;
}

