/**
 * @summary Posts a file to Binary Storage
 * @description Uploads a binary file to Cloudforce One's binary database for malware analysis and threat intelligence correlation.
 * @link /accounts/{accountId}/cloudforce-one/binary
 */
export async function postBinDBPost(
	{
		pathParams,
		body,
		config,
	}: {
		pathParams: PostBinDBPostPath;
		body: PostBinDBPostBody;
		config?: Partial<FetcherConfig> & { client?: typeof defaultClient };
	} = {} as any,
) {
	const { client: request = defaultClient, ...requestConfig } = config ?? {};

	if (pathParams?.accountId == null || String(pathParams.accountId) === "") {
		throw new Error(`Missing required path parameter: accountId`);
	}
	const formData = new FormData();
	if (body) {
		for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
			for (const item of Array.isArray(value) ? value : [value]) {
				if (typeof item === "string" || item instanceof Blob) {
					formData.append(key, item);
				} else if (
					typeof item === "number" ||
					typeof item === "boolean" ||
					typeof item === "bigint"
				) {
					formData.append(key, String(item));
				} else if (item != null) {
					formData.append(key, JSON.stringify(item));
				}
			}
		}
	}
	const data = await request<
		PostBinDBPostResponse,
		ErrorWrapper<PostBinDBPostStatus400>,
		FormData,
		Record<string, string>,
		Record<string, string>,
		PostBinDBPostPath
	>({
		method: "POST",
		url: `/accounts/${encodeURIComponent(String(pathParams.accountId))}/cloudforce-one/binary`,
		body: formData,
		...requestConfig,
		headers: { "Content-Type": "multipart/form-data", ...requestConfig.headers },
	});

	return data;
}

