/**
 * @summary Uploads a new version for a document fingerprint.
 * @description Uploads a new document to create or update a fingerprint. The document structure is analyzed to enable detection of similar documents.
 * @link /accounts/{accountId}/dlp/document_fingerprints/{documentFingerprintId}
 */
export async function dlpDocumentFingerprintsUpload(
	{
		pathParams,
		body,
		config,
	}: {
		pathParams: DlpDocumentFingerprintsUploadPath;
		body: DlpDocumentFingerprintsUploadBody;
		config?: Partial<FetcherConfig> & { client?: typeof defaultClient };
	} = {} as any,
) {
	const { client: request = defaultClient, ...requestConfig } = config ?? {};

	if (pathParams?.accountId == null || String(pathParams.accountId) === "") {
		throw new Error(`Missing required path parameter: accountId`);
	}

	if (
		pathParams?.documentFingerprintId == null ||
		String(pathParams.documentFingerprintId) === ""
	) {
		throw new Error(`Missing required path parameter: documentFingerprintId`);
	}
	const formData = new FormData();
	if (body) {
		for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
			for (const item of Array.isArray(value) ? value : [value]) {
				if (typeof item === "string" || item instanceof Blob) {
					formData.append(key, item);
				} else if (
					typeof item === "number" ||
					typeof item === "boolean" ||
					typeof item === "bigint"
				) {
					formData.append(key, String(item));
				} else if (item != null) {
					formData.append(key, JSON.stringify(item));
				}
			}
		}
	}
	const data = await request<
		DlpDocumentFingerprintsUploadResponse,
		ErrorWrapper<DlpDocumentFingerprintsUploadStatus400>,
		FormData,
		Record<string, string>,
		Record<string, string>,
		DlpDocumentFingerprintsUploadPath
	>({
		method: "PUT",
		url: `/accounts/${encodeURIComponent(String(pathParams.accountId))}/dlp/document_fingerprints/${encodeURIComponent(String(pathParams.documentFingerprintId))}`,
		body: formData,
		...requestConfig,
		headers: { "Content-Type": "multipart/form-data", ...requestConfig.headers },
	});

	return data;
}

