/**
 * @summary Upload an image
 * @description Upload an image to CF Images. Images up to 10 Megabytes can be uploaded using a
 * single HTTP POST (multipart/form-data) request by sending an image file or
 * passing a URL accessible to the API.
 * @link /accounts/{accountId}/images/v1
 */
export async function cloudflareImagesUploadAnImageViaUrl(
	{
		pathParams,
		body,
		config,
	}: {
		pathParams: CloudflareImagesUploadAnImageViaUrlPath;
		body: CloudflareImagesUploadAnImageViaUrlBody;
		config?: Partial<FetcherConfig> & { client?: typeof defaultClient };
	} = {} as any,
) {
	const { client: request = defaultClient, ...requestConfig } = config ?? {};

	if (pathParams?.accountId == null || String(pathParams.accountId) === "") {
		throw new Error(`Missing required path parameter: accountId`);
	}
	const formData = new FormData();
	if (body) {
		for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
			for (const item of Array.isArray(value) ? value : [value]) {
				if (typeof item === "string" || item instanceof Blob) {
					formData.append(key, item);
				} else if (
					typeof item === "number" ||
					typeof item === "boolean" ||
					typeof item === "bigint"
				) {
					formData.append(key, String(item));
				} else if (item != null) {
					formData.append(key, JSON.stringify(item));
				}
			}
		}
	}
	const data = await request<
		CloudflareImagesUploadAnImageViaUrlResponse,
		ErrorWrapper<CloudflareImagesUploadAnImageViaUrlStatus400>,
		FormData,
		Record<string, string>,
		Record<string, string>,
		CloudflareImagesUploadAnImageViaUrlPath
	>({
		method: "POST",
		url: `/accounts/${encodeURIComponent(String(pathParams.accountId))}/images/v1`,
		body: formData,
		...requestConfig,
		headers: { "Content-Type": "multipart/form-data", ...requestConfig.headers },
	});

	return data;
}

